<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { api } from './api'; import { useAuth } from './stores/auth';
const auth=useAuth(), graph=ref<any>(), progress=ref<any[]>([]), focus=ref<any>();
onMounted(async()=>{graph.value=await api('/skills');if(auth.token){try{progress.value=await api('/users/me/skills')}catch{}}focus.value=graph.value.nodes[0]});
const current=computed(()=>progress.value.find(item=>item.skill.slug===focus.value?.slug));
</script>
<template><section class="experience skills-experience" v-if="graph"><div class="experience-heading compact"><div><span class="eyebrow">SKILL MAP / 能力路线</span><h1>让知识点，<br>变成可见的进度</h1><p>课程与解题成果由后端写入个人能力档案。选择节点，查看当前积累与推荐下一步。</p></div><div class="skill-summary"><span>个人能力记录</span><b>{{progress.filter(item=>item.xp>0).length}}<small>个已积累方向</small></b><p>{{auth.user?'数据随本地账号保存':'登录后开始记录进度'}}</p></div></div><div class="skill-workbench"><section class="skill-map"><div class="map-grid"></div><button v-for="(node,index) in graph.nodes" :key="node.slug" :style="{'--x':(10+(index%3)*37)+'%','--y':(18+Math.floor(index/3)*52)+'%'}" :class="{selected:focus?.slug===node.slug,learned:progress.find(item=>item.skill.slug===node.slug)?.xp>0}" @click="focus=node"><i>{{String(index+1).padStart(2,'0')}}</i><span>{{node.category}}</span><b>{{node.name}}</b><small>{{progress.find(item=>item.skill.slug===node.slug)?.xp||0}} XP</small></button><svg viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M19 33 L50 33 L82 33 M19 33 L19 74 L50 74 L82 74"/></svg></section><aside class="skill-detail" v-if="focus"><span class="eyebrow">当前节点</span><h2>{{focus.name}}</h2><p>{{focus.category}} · 通过课程、题目与复盘积累经验。</p><div class="xp-bar"><span :style="{width:Math.min(100,(current?.xp||0))+'%'}"></span></div><div class="detail-row"><span>已获得经验</span><b>{{current?.xp||0}} XP</b></div><div class="detail-row"><span>当前状态</span><b>{{current?.status==='LEARNING'?'学习中':'等待开始'}}</b></div><RouterLink to="/learning" class="dark-action">去学习中心 <i>→</i></RouterLink></aside></div></section><section v-else class="experience loading">正在读取能力图谱…</section></template>
